create or replace function public.claim_pilot_assessment_to_current_profile(p_assessment_id uuid) returns jsonb language plpgsql security definer set search_path=public,auth,extensions as $$ declare v_a public.assessments; v_p public.profiles; v_uid uuid; begin v_uid:=auth.uid(); if v_uid is null then raise exception 'authentication_required'; end if; select * into v_a from public.assessments where id=p_assessment_id; if v_a.id is null then raise exception 'assessment_not_found'; end if; if v_a.profile_id is not null then select * into v_p from public.profiles where id=v_a.profile_id; if v_p.user_id is distinct from v_uid then raise exception 'assessment_not_owner'; end if; return jsonb_build_object('assessment_id',v_a.id,'profile_id',v_p.id,'claimed',false,'already_owned',true); end if; select * into v_p from public.profiles where user_id=v_uid limit 1; if v_p.id is null then select * into v_p from public.get_or_create_current_profile(); end if; if v_a.status not in ('in_progress','completed') then raise exception 'assessment_not_claimable'; end if; update public.assessments set profile_id=v_p.id where id=v_a.id and profile_id is null; if not found then raise exception 'assessment_claim_conflict'; end if; return jsonb_build_object('assessment_id',v_a.id,'profile_id',v_p.id,'claimed',true,'already_owned',false); end; $$; revoke all on function public.claim_pilot_assessment_to_current_profile(uuid) from public,anon,authenticated; grant execute on function public.claim_pilot_assessment_to_current_profile(uuid) to authenticated;